import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"跟单交易","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/follow.md","filePath":"zh/guide/follow.md","lastUpdated":1790683574000}'),l={name:"zh/guide/follow.md"};function o(r,a,i,p,h,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="跟单交易" tabindex="-1">跟单交易 <a class="header-anchor" href="#跟单交易" aria-label="Permalink to &quot;跟单交易&quot;">​</a></h1><p>跟单是平台的社交化交易玩法：<strong>带单员</strong>发起带单计划并生成跟单码，<strong>用户</strong>凭码一键跟投，到点由系统统一建仓与结算。</p><h2 id="整体流程" tabindex="-1">整体流程 <a class="header-anchor" href="#整体流程" aria-label="Permalink to &quot;整体流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后台给某用户开通「带单权限」</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>带单员在用户端发起带单计划 → 生成专属跟单码</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>用户输入跟单码 → 一键跟投（无需自己盯盘）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>到点系统统一批量建仓</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>结算后自动回写各自盈亏</span></span></code></pre></div><h2 id="运营侧要做什么" tabindex="-1">运营侧要做什么 <a class="header-anchor" href="#运营侧要做什么" aria-label="Permalink to &quot;运营侧要做什么&quot;">​</a></h2><h3 id="一、开通带单权限" tabindex="-1">一、开通带单权限 <a class="header-anchor" href="#一、开通带单权限" aria-label="Permalink to &quot;一、开通带单权限&quot;">​</a></h3><p>跟单码不是所有用户都能发。需要在后台为指定用户<strong>开通带单权限</strong>，未开通的用户无法发起带单计划。</p><h3 id="二、控制每日发码额度" tabindex="-1">二、控制每日发码额度 <a class="header-anchor" href="#二、控制每日发码额度" aria-label="Permalink to &quot;二、控制每日发码额度&quot;">​</a></h3><p>后台可限制带单员<strong>每日能发多少个跟单码</strong>，避免滥发。</p><h3 id="三、跟单管理" tabindex="-1">三、跟单管理 <a class="header-anchor" href="#三、跟单管理" aria-label="Permalink to &quot;三、跟单管理&quot;">​</a></h3><p>后台提供完整的跟单记录查询：谁发的码、谁跟了、建仓与结算结果如何。</p><h2 id="资金安全" tabindex="-1">资金安全 <a class="header-anchor" href="#资金安全" aria-label="Permalink to &quot;资金安全&quot;">​</a></h2><ul><li>全流程由系统托管，资金动作全程留痕</li><li><strong>跟投失败即时原路退款</strong>，不会出现扣了钱又没建仓的情况</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>用户说跟单码无效？</strong> 先确认：① 该码是否已过期；② 带单计划是否已到建仓时点（已建仓的计划不再接受新跟投）；③ 码是否输错。</p><p><strong>用户跟投了但没建仓？</strong> 查跟单记录中该笔的状态。跟投失败会原路退款，用户可在资金流水中看到退款记录。</p>`,16)])])}const g=s(l,[["render",o]]);export{u as __pageData,g as default};
